import os
import json
import uuid
import time
import base64
import threading
from flask import Flask, request, Response, jsonify, send_from_directory, send_file
from cerebras.cloud.sdk import Cerebras
from google import genai
from google.genai import types

app = Flask(__name__)

sessions = {}
sessions_lock = threading.Lock()

images_store = {}
images_lock = threading.Lock()

GEMINI_VISION_SYSTEM = (
    "You are a vision assistant. Briefly and naturally describe the key elements "
    "of this image in 2-4 sentences. If the user has asked a specific question about "
    "it, answer that question directly as part of your response. Be concise and "
    "conversational — do not produce an exhaustive list of every detail."
)

GLM_SYSTEM = (
    "You are a helpful, thoughtful AI assistant. When an image description is provided "
    "as [IMAGE CONTEXT] in the conversation, use that information naturally to answer "
    "the user's question — as if you can directly see the image. Never say things like "
    "'based on the description', 'as described', 'az adott leírás', or similar phrases. "
    "Just respond directly and naturally."
)


def sse(data):
    return f"data:{json.dumps(data, ensure_ascii=False)}\n\n"


def get_session(session_id):
    with sessions_lock:
        if session_id not in sessions:
            sessions[session_id] = {
                "messages": [],
                "preview": "",
                "updated_at": int(time.time()),
            }
        return sessions[session_id]


def append_message(session_id, role, content, has_image=False, image_keys=None, vision_context=None):
    with sessions_lock:
        if session_id not in sessions:
            sessions[session_id] = {
                "messages": [],
                "preview": "",
                "updated_at": int(time.time()),
            }
        msg = {
            "role": role,
            "content": content,
            "has_image": has_image,
            "image_keys": image_keys or [],
            "vision_context": vision_context or "",
            "ts": int(time.time()),
        }
        sessions[session_id]["messages"].append(msg)
        sessions[session_id]["updated_at"] = int(time.time())
        if not sessions[session_id]["preview"]:
            text = content if isinstance(content, str) else ""
            sessions[session_id]["preview"] = text[:80] if text else ("Kép" if has_image else "Chat")


def delete_session(session_id):
    with sessions_lock:
        if session_id in sessions:
            del sessions[session_id]


def store_image(img_payload):
    key = str(uuid.uuid4())
    with images_lock:
        images_store[key] = img_payload
    return key


@app.route("/")
def index():
    return send_file("index.html")


@app.route("/static/<path:filename>")
def static_files(filename):
    return send_from_directory("static", filename)


@app.route("/api/sessions", methods=["GET"])
def list_sessions():
    with sessions_lock:
        result = []
        for sid, data in sessions.items():
            result.append({
                "session_id": sid,
                "preview": data.get("preview", "Chat"),
                "count": len(data.get("messages", [])),
                "updated_at": data.get("updated_at", 0),
            })
    result.sort(key=lambda x: x["updated_at"], reverse=True)
    return jsonify({"sessions": result})


@app.route("/api/session/<session_id>", methods=["GET"])
def get_session_messages(session_id):
    with sessions_lock:
        data = sessions.get(session_id)
    if not data:
        return jsonify({"messages": []}), 404
    messages = []
    for msg in data.get("messages", []):
        messages.append({
            "role": msg["role"],
            "content": msg["content"],
            "has_image": msg.get("has_image", False),
            "image_keys": msg.get("image_keys", []),
            "ts": msg.get("ts", 0),
        })
    return jsonify({"messages": messages})


@app.route("/api/image/<image_key>", methods=["GET"])
def get_image(image_key):
    with images_lock:
        img = images_store.get(image_key)
    if not img:
        return jsonify({"error": "not found"}), 404
    raw = base64.b64decode(img["data"])
    return Response(raw, mimetype=img["media_type"])


@app.route("/api/history", methods=["GET"])
def get_history():
    session_id = request.args.get("session_id", "")
    if not session_id:
        return jsonify([])
    with sessions_lock:
        data = sessions.get(session_id)
    if not data:
        return jsonify([])
    result = []
    for msg in data.get("messages", []):
        result.append({
            "role": msg["role"],
            "content": msg["content"],
            "ts": msg.get("ts", 0),
        })
    return jsonify(result)


@app.route("/api/history", methods=["DELETE"])
def delete_history():
    session_id = request.args.get("session_id", "")
    if session_id:
        delete_session(session_id)
    return jsonify({"ok": True})


def _chat_generate(session_id, raw_message, images):
    yield sse({"type": "session", "session_id": session_id})

    vision_context = ""
    image_keys = []
    has_image = bool(images)

    if images:
        try:
            gemini_client = genai.Client(api_key=os.environ.get("GEMINI_API_KEY"))

            parts = []
            for img in images:
                raw_bytes = base64.b64decode(img["data"])
                parts.append(
                    types.Part(
                        inline_data=types.Blob(
                            mime_type=img["media_type"], data=raw_bytes
                        )
                    )
                )
                image_keys.append(store_image(img))

            question_hint = f' The user is asking: "{raw_message}"' if raw_message else ""
            parts.append(
                types.Part.from_text(
                    text=f"Describe this image briefly and naturally.{question_hint}"
                )
            )

            contents = [types.Content(role="user", parts=parts)]
            config = types.GenerateContentConfig(
                max_output_tokens=512,
                system_instruction=[types.Part.from_text(text=GEMINI_VISION_SYSTEM)],
            )

            yield sse({"type": "reasoning_start"})

            for chunk in gemini_client.models.generate_content_stream(
                model="gemini-2.0-flash",
                contents=contents,
                config=config,
            ):
                if chunk.text:
                    vision_context += chunk.text
                    yield sse({"type": "reasoning", "text": chunk.text})

            yield sse({"type": "reasoning_end"})

        except Exception as gemini_err:
            yield sse({"type": "reasoning_end"})
            yield sse({"type": "warning", "message": "Kép elemzés sikertelen: " + str(gemini_err)})

    session_data = get_session(session_id)
    history = session_data.get("messages", [])

    cerebras_messages = [{"role": "system", "content": GLM_SYSTEM}]
    for msg in history:
        role = msg["role"]
        if role not in ("user", "assistant"):
            continue
        content = msg["content"]
        stored_ctx = msg.get("vision_context", "")
        if role == "user" and stored_ctx:
            if content:
                content = f"{content}\n\n[IMAGE CONTEXT]\n{stored_ctx}\n[/IMAGE CONTEXT]"
            else:
                content = f"[IMAGE CONTEXT]\n{stored_ctx}\n[/IMAGE CONTEXT]"
        cerebras_messages.append({"role": role, "content": content})

    user_content = raw_message or ""
    if vision_context:
        user_content = (
            f"{raw_message}\n\n[IMAGE CONTEXT]\n{vision_context}\n[/IMAGE CONTEXT]"
            if raw_message
            else f"[IMAGE CONTEXT]\n{vision_context}\n[/IMAGE CONTEXT]"
        )

    cerebras_messages.append({"role": "user", "content": user_content})

    append_message(
        session_id,
        "user",
        raw_message or ("[Kép]" if has_image else ""),
        has_image=has_image,
        image_keys=image_keys,
        vision_context=vision_context,
    )

    try:
        cerebras_client = Cerebras(api_key=os.environ.get("CEREBRAS_API_KEY"))

        stream = cerebras_client.chat.completions.create(
            messages=cerebras_messages,
            model="zai-glm-4.7",
            stream=True,
            max_completion_tokens=16000,
            temperature=0.7,
            clear_thinking=True,
        )

        full_response = ""
        thinking_started = False

        for chunk in stream:
            delta = chunk.choices[0].delta

            thinking = getattr(delta, "thinking_content", None) or ""
            content = delta.content or ""

            if thinking:
                if not thinking_started and not has_image:
                    thinking_started = True
                    yield sse({"type": "reasoning_start"})
                elif not thinking_started and has_image:
                    thinking_started = True
                yield sse({"type": "reasoning", "text": thinking})

            if content:
                if thinking_started and not has_image:
                    thinking_started = False
                    yield sse({"type": "reasoning_end"})
                full_response += content
                yield sse({"type": "content", "text": content})

        if thinking_started:
            yield sse({"type": "reasoning_end"})

        append_message(session_id, "assistant", full_response)

    except Exception as err:
        yield sse({"type": "error", "message": "Szerverhiba: " + str(err)})


@app.route("/api/chat", methods=["POST"])
def chat():
    data = request.get_json(force=True)
    raw_message = data.get("message", "")
    session_id = data.get("session_id") or str(uuid.uuid4())
    images = data.get("images", [])

    return Response(
        _chat_generate(session_id, raw_message, images),
        mimetype="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no",
        },
    )


@app.route("/api/agent", methods=["POST"])
def agent():
    data = request.get_json(force=True)
    raw_message = data.get("message", "")
    session_id = data.get("session_id") or str(uuid.uuid4())
    images = data.get("images", [])

    return Response(
        _chat_generate(session_id, raw_message, images),
        mimetype="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no",
        },
    )


if __name__ == "__main__":
    port = int(os.environ.get("PORT", 5000))
    app.run(host="0.0.0.0", port=port, debug=False, threaded=True)

